const normalise = v => String(v ?? '').normalize('NFKC').trim().toLocaleLowerCase().replace(/\s+/g, ' ');
/** Exact named-area match only. Never guess a ward from coordinates without boundary polygons. */
export function wardForRecord(r) {
  const number = r.wardNumber ?? r.ward?.number;
  if (number != null) return wards.find(w => String(w.wardNumber) === String(number)) ?? null;
  const name = normalise(r.wardName ?? r.ward?.name ?? r.area);
  const matches = wards.filter(w => normalise(w.wardName) === name);
  return matches.length === 1 ? matches[0] : null;
}
export const zones = [...new Map(wards.map(w => [w.zoneNumber, {zoneNumber: w.zoneNumber, zoneName: w.zoneName}])).values()];
export function geographyFilters(id) {
  return `<div class="field"><label for="${id}-zone">Zone name</label><select id="${id}-zone" name="zone"><option value="">All zones</option>${zones.map(z => `<option value="${z.zoneNumber}">${z.zoneName}</option>`).join('')}<option value="unassigned">Unassigned / outside directory</option></select></div>
    <div class="field"><label for="${id}-ward">Ward name</label><select id="${id}-ward" name="ward"><option value="">All wards</option>${wards.map(w => `<option value="${w.wardNumber}" data-zone="${w.zoneNumber}">${w.wardName} · Ward ${w.wardNumber}</option>`).join('')}<option value="unassigned">Unassigned / outside directory</option></select></div>`;
}
export function syncWardOptions(form) {
  const zone = form.elements.zone?.value;
  const select = form.elements.ward;
  if (!select) return;
  for (const option of select.options) {
    option.hidden = !!zone && !!option.value && (zone === 'unassigned' ? option.value !== 'unassigned' : option.dataset.zone !== zone);
    option.disabled = option.hidden;
  }
  if (select.selectedOptions[0]?.disabled) select.value = '';
}
